import{_ as e,o as i,c as s,a2 as n}from"./chunks/framework.D7EuCHIT.js";const u=JSON.parse('{"title":"流派、文件夹与语言规则","description":"","frontmatter":{},"headers":[],"relativePath":"config/classification.md","filePath":"config/classification.md","lastUpdated":1791828780000}'),t={name:"config/classification.md"};function r(o,a,l,p,c,d){return i(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="流派、文件夹与语言规则" tabindex="-1">流派、文件夹与语言规则 <a class="header-anchor" href="#流派、文件夹与语言规则" aria-label="Permalink to &quot;流派、文件夹与语言规则&quot;">​</a></h1><p>个人页只显示曲库确实拥有的分类，分组复用现有封面与折叠样式。</p><h2 id="流派" tabindex="-1">流派 <a class="header-anchor" href="#流派" aria-label="Permalink to &quot;流派&quot;">​</a></h2><p><code>profile.genre_rules</code> 为换行分隔的规则，每行 <code>展示名=alias|alias</code>。大小写/空格/连字符规范化按当前本地规则处理。<code>genre_numbers</code> 是有顺序的 ID3 数字标签映射；改顺序会改变数字标签含义，不能随便排序。</p><div class="language-toml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">profile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">genre_rules = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Rock=rock|摇滚</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Jazz=jazz|爵士&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>这是用两条规则替换整份字符串，不是在默认大列表上自动追加。要保留全量默认别名，应先从<a href="/LyraPlayer-docs-site/config/reference/ui-profile">完整 profile 默认值</a>复制并增补。未知用户标签保留原文，不从歌名猜流派。</p><h2 id="文件夹" tabindex="-1">文件夹 <a class="header-anchor" href="#文件夹" aria-label="Permalink to &quot;文件夹&quot;">​</a></h2><p>按存储卷与完整位置分组；同名但不同位置的目录不合并。展示 basename 与完整路径。unknown_folder 只决定无法取得目录时的标签，不伪造目录来源。</p><h2 id="语言" tabindex="-1">语言 <a class="header-anchor" href="#语言" aria-label="Permalink to &quot;语言&quot;">​</a></h2><p>language_scripts 按字母范围识别，language_words 提供词表，language_labels 决定显示标签。word_weight、minimum_word_score、script_fraction、kana_priority 控制本地规则。拉丁共享字母、罗马字、短标题和混合语言存在歧义，应回退未知。</p><p>优先歌词正文，忽略译文/注音；没有可读歌词再用歌名。有歌词但不能识别时不强制标题结论。侧车后缀和读取预算可配，Android 不可读文件不会当作已经读取。</p><p>后台索引批次完成后发布语言样本与分组，避免把一半索引状态当完整语言目录。外部源可提供可选 catalog 字段，也可替换 classification rules。</p><p>显示类目文案在 <code>[profile_copy]</code>，规则标签与未知标签在 <code>[profile]</code>，两者别混放。</p>`,13)])])}const k=e(t,[["render",r]]);export{u as __pageData,k as default};
